/**
 * Save generated bytes (MIDI, ABC, …) to a file the user picks.
 *
 * In the desktop app, pywebview's WebView can't do browser downloads, so the
 * native window exposes `save_file`, which opens the Windows Save dialog and
 * writes the bytes there. In a normal browser (development) we fall back to a
 * regular download.
 */
export type SaveKind = "midi" | "abc";

const MIME: Record<SaveKind, string> = {
  midi: "audio/midi",
  abc: "text/vnd.abc",
};

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

/** Returns the saved path (desktop), "downloaded" (browser), or null if cancelled. */
export async function saveFile(name: string, data: Uint8Array | string, kind: SaveKind): Promise<string | null> {
  const bytes = typeof data === "string" ? new TextEncoder().encode(data) : data;
  const bridge = (window as any).pywebview?.api;
  if (bridge?.save_file) {
    const path = await bridge.save_file(name, toBase64(bytes), kind);
    return path || null;
  }
  const url = URL.createObjectURL(new Blob([new Uint8Array(bytes)], { type: MIME[kind] }));
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return "downloaded";
}
